public class P {
  public static void main(String[] a){
    for (int n : new int[]{6,12}) {
      BigDecimal total = n==6 ? new BigDecimal("431.45") : new BigDecimal("101.00");
      BigDecimal i = new BigDecimal("0.0199");
      BigDecimal f = BigDecimal.ONE.add(i).pow(n);
      BigDecimal d = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(f, MathContext.DECIMAL128));
      BigDecimal p = total.multiply(i).divide(d, MathContext.DECIMAL128).setScale(2, RoundingMode.HALF_EVEN);
      BigDecimal tf = p.multiply(BigDecimal.valueOf(n)).setScale(2, RoundingMode.HALF_EVEN);
      System.out.println(n+"x parcela="+p+" totalFinal="+tf+" ajuste="+tf.subtract(total));
    }
  }
}
