                List.of(CAMISETA), "DRONE", "PROMO999", "CRIPTO", 99, "DIAMANTE", "EUROPA")))
                .isEqualTo(Erro.NIVEL_CLUBE_INVALIDO);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "DRONE", "PROMO999", "CRIPTO", 99, "BRONZE", "EUROPA")))
                .isEqualTo(Erro.REGIAO_INVALIDA);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "DRONE", "PROMO999", "CRIPTO", 99, "BRONZE", "SUDESTE")))
                .isEqualTo(Erro.MODALIDADE_INVALIDA);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "MOTOBOY", "PROMO999", "CRIPTO", 99, "BRONZE", "SUDESTE")))
                .isEqualTo(Erro.CUPOM_INVALIDO);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "MOTOBOY", "MENOS50", "CRIPTO", 99, "BRONZE", "SUDESTE")))
                .isEqualTo(Erro.CUPOM_NAO_APLICAVEL);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "MOTOBOY", null, "CRIPTO", 99, "BRONZE", "SUDESTE")))
                .isEqualTo(Erro.FORMA_PAGAMENTO_INVALIDA);
        assertThat(recusa(new ResumoRequisicao(
                List.of(CAMISETA), "MOTOBOY", null, "BOLETO", 99, "BRONZE", "SUDESTE")))
                .isEqualTo(Erro.PARCELAMENTO_INVALIDO);
    }

    private Erro recusa(ResumoRequisicao requisicao) {
        PedidoRecusadoException excecao = (PedidoRecusadoException) assertThatThrownBy(
                () -> servico.calcular(requisicao))
                .isInstanceOf(PedidoRecusadoException.class)
                .actual();
        return excecao.erro();
    }

    private static ResumoRequisicao pedido(List<ItemRequisicao> itens) {
        return new ResumoRequisicao(itens, "RETIRADA_LOJA", null, "PIX", 1, "BRONZE", "SUDESTE");
    }

    private static Requisicoes valido() {
        return new Requisicoes(pedido(List.of(CAMISETA)));
    }

    /** Monta variacoes de uma requisicao valida, mudando um campo por vez. */
    private record Requisicoes(ResumoRequisicao base) {

        ResumoRequisicao comItens(List<ItemRequisicao> itens) {
            return trocar(itens, base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comEntrega(String entrega) {
            return trocar(base.itens(), entrega, base.cupom(),
                    base.formaPagamento(), base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comCupom(String cupom) {
            return trocar(base.itens(), base.modalidadeEntrega(), cupom,
                    base.formaPagamento(), base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comPagamento(String pagamento) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    pagamento, base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comParcelas(Integer parcelas) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), parcelas, base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comNivel(String nivel) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), base.parcelas(), nivel, base.regiao());
        }

        ResumoRequisicao comRegiao(String regiao) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), base.parcelas(), base.nivelClube(), regiao);
        }

        private ResumoRequisicao trocar(List<ItemRequisicao> itens, String entrega, String cupom,
                                        String pagamento, Integer parcelas, String nivel, String regiao) {
            return new ResumoRequisicao(itens, entrega, cupom, pagamento, parcelas, nivel, regiao);
        }
    }
}
