                    base.formaPagamento(), base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comPagamento(String pagamento) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    pagamento, base.parcelas(), base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comParcelas(Integer parcelas) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), parcelas, base.nivelClube(), base.regiao());
        }

        ResumoRequisicao comNivel(String nivel) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), base.parcelas(), nivel, base.regiao());
        }

        ResumoRequisicao comRegiao(String regiao) {
            return trocar(base.itens(), base.modalidadeEntrega(), base.cupom(),
                    base.formaPagamento(), base.parcelas(), base.nivelClube(), regiao);
        }

        private ResumoRequisicao trocar(List<ItemRequisicao> itens, String entrega, String cupom,
                                        String pagamento, Integer parcelas, String nivel, String regiao) {
            return new ResumoRequisicao(itens, entrega, cupom, pagamento, parcelas, nivel, regiao);
        }
    }
