2	
3	import com.loja.checkout.api.ItemRequisicao;
4	import com.loja.checkout.api.ResumoRequisicao;
5	import com.loja.checkout.api.ResumoResposta;
6	import com.loja.checkout.clube.NivelClube;
7	import com.loja.checkout.clube.Niveis;
8	import com.loja.checkout.cupom.ContextoCupom;
9	import com.loja.checkout.cupom.Cupons;
10	import com.loja.checkout.dominio.Dinheiro;
11	import com.loja.checkout.dominio.Erro;
12	import com.loja.checkout.dominio.ItemPedido;
13	import com.loja.checkout.dominio.Pedido;
14	import com.loja.checkout.dominio.PedidoRecusadoException;
15	import com.loja.checkout.dominio.Regiao;
16	import com.loja.checkout.entrega.ModalidadeEntrega;
17	import com.loja.checkout.entrega.Modalidades;
18	import com.loja.checkout.pagamento.FormaPagamento;
19	import com.loja.checkout.pagamento.FormasPagamento;
20	import com.loja.checkout.pagamento.Liquidacao;
21	import org.springframework.stereotype.Service;
22	
23	import java.math.BigDecimal;
24	import java.util.List;
25	
26	/**
27	 * A sequencia do calculo do resumo, igual para todo pedido. O que varia de
28	 * caso para caso esta nas implementacoes de entrega, cupom, clube e
29	 * pagamento; aqui so se pergunta a cada uma.
30	 */
31	@Service
32	public class CalculoResumoService {
33	
34	    private static final int PARCELAS_PADRAO = 1;
35	
36	    public ResumoResposta calcular(ResumoRequisicao requisicao) {
37	        Pedido pedido = pedidoValido(requisicao);
38	        NivelClube nivel = Niveis.exigir(requisicao.nivelClube());
39	        Regiao regiao = Regiao.exigir(requisicao.regiao());
40	        ModalidadeEntrega entrega = entregaDisponivel(requisicao.modalidadeEntrega(), pedido);
41	
42	        BigDecimal subtotalProdutos = pedido.subtotal();
43	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.ZERO : entrega.frete(pedido);
44	        BigDecimal descontoCupom = Cupons.desconto(requisicao.cupom(),
45	                new ContextoCupom(pedido, subtotalProdutos, frete));
46	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
47	        BigDecimal totalPedido = Dinheiro.centavos(
48	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
49	
50	        int parcelas = requisicao.parcelas() == null ? PARCELAS_PADRAO : requisicao.parcelas();
51	        FormaPagamento pagamento = pagamentoDisponivel(
52	                requisicao.formaPagamento(), parcelas, totalPedido);
53	        Liquidacao liquidacao = pagamento.liquidar(totalPedido, parcelas);
54	
55	        return new ResumoResposta(
56	                subtotalProdutos,
57	                descontoCupom,
58	                frete,
59	                entrega.prazoDias(),
60	                seguro,
61	                Dinheiro.centavos(liquidacao.totalFinal().subtract(totalPedido)),
62	                liquidacao.totalFinal(),
63	                parcelas,
64	                liquidacao.valorParcela(),
65	                nivel.credito(subtotalProdutos),
66	                nivel.brinde(subtotalProdutos));
67	    }
68	
69	    private Pedido pedidoValido(ResumoRequisicao requisicao) {
70	        List<ItemRequisicao> itens = requisicao.itens();
71	        if (itens == null || itens.isEmpty()) {
72	            throw new PedidoRecusadoException(Erro.PEDIDO_INVALIDO);
73	        }
74	        return new Pedido(itens.stream().map(this::itemValido).toList());
75	    }
76	
77	    private ItemPedido itemValido(ItemRequisicao item) {
78	        if (item == null
79	                || naoEPositivo(item.precoUnitario())
80	                || naoEPositivo(item.pesoKg())
81	                || item.quantidade() == null
82	                || item.quantidade() <= 0) {
83	            throw new PedidoRecusadoException(Erro.PEDIDO_INVALIDO);
84	        }
85	        return new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
86	    }
87	
88	    private boolean naoEPositivo(BigDecimal valor) {
89	        return valor == null || valor.signum() <= 0;
90	    }
91	
92	    private ModalidadeEntrega entregaDisponivel(String codigo, Pedido pedido) {
93	        ModalidadeEntrega entrega = Modalidades.exigir(codigo);
94	        if (!entrega.atende(pedido)) {
95	            throw new PedidoRecusadoException(Erro.MODALIDADE_INDISPONIVEL);
96	        }
97	        return entrega;
98	    }
99	
100	    private FormaPagamento pagamentoDisponivel(String codigo, int parcelas, BigDecimal totalPedido) {
101	        FormaPagamento pagamento = FormasPagamento.exigir(codigo);
102	        if (!pagamento.permiteParcelas(parcelas)) {
103	            throw new PedidoRecusadoException(Erro.PARCELAMENTO_INVALIDO);
104	        }
105	        if (!pagamento.atende(totalPedido)) {
106	            throw new PedidoRecusadoException(Erro.FORMA_PAGAMENTO_INDISPONIVEL);
107	        }
108	        return pagamento;
109	    }
110	}
