3	import java.util.LinkedHashMap;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.Optional;
7	import java.util.function.Function;
8	
9	/**
10	 * Catalogo de casos de um eixo de variacao: traduz o codigo recebido do site
11	 * na instancia que carrega a regra daquele caso. A escolha do caso e sempre
12	 * uma busca aqui, nunca uma cadeia de condicoes.
13	 */
14	public final class Catalogo<T> {
15	
16	    private final Map<String, T> porCodigo;
17	
18	    private Catalogo(Map<String, T> porCodigo) {
19	        this.porCodigo = porCodigo;
20	    }
21	
22	    public static <T> Catalogo<T> de(List<T> casos, Function<T, String> codigo) {
23	        Map<String, T> mapa = new LinkedHashMap<>();
24	        casos.forEach(caso -> mapa.put(codigo.apply(caso), caso));
25	        return new Catalogo<>(Map.copyOf(mapa));
26	    }
27	
28	    public Optional<T> buscar(String codigo) {
29	        return codigo == null ? Optional.empty() : Optional.ofNullable(porCodigo.get(codigo));
30	    }
31	}
