2	
3	import com.loja.checkout.dominio.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	/** Cartao de credito: ate 3x sem juros, de 4x a 12x com juros (tabela Price). */
10	public final class Cartao implements FormaPagamento {
11	
12	    private static final int PARCELAS_MAXIMAS = 12;
13	    private static final int PARCELAS_SEM_JUROS = 3;
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean permiteParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
25	    }
26	
27	    @Override
28	    public boolean atende(BigDecimal totalPedido) {
29	        return true;
30	    }
31	
32	    @Override
33	    public Liquidacao liquidar(BigDecimal totalPedido, int parcelas) {
34	        return parcelas <= PARCELAS_SEM_JUROS
35	                ? semJuros(totalPedido, parcelas)
36	                : comJuros(totalPedido, parcelas);
37	    }
38	
39	    /** O valor final e o proprio total do pedido; a parcela e o total dividido. */
40	    private Liquidacao semJuros(BigDecimal totalPedido, int parcelas) {
41	        BigDecimal valorParcela = totalPedido.divide(
42	                BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
43	        return new Liquidacao(Dinheiro.centavos(totalPedido), valorParcela);
44	    }
45	
46	    /** Tabela Price: parcela = total x taxa / (1 - (1 + taxa)^-parcelas). */
47	    private Liquidacao comJuros(BigDecimal totalPedido, int parcelas) {
48	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
49	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, PRECISAO));
50	        BigDecimal valorParcela = Dinheiro.centavos(
51	                totalPedido.multiply(TAXA_MENSAL).divide(divisor, PRECISAO));
52	        BigDecimal totalFinal = Dinheiro.centavos(
53	                valorParcela.multiply(BigDecimal.valueOf(parcelas)));
54	        return new Liquidacao(totalFinal, valorParcela);
55	    }
56	}
