23	        return recusar(Erro.PEDIDO_INVALIDO);
24	    }
25	
26	    private ResponseEntity<ErroResposta> recusar(Erro erro) {
27	        return ResponseEntity.badRequest().body(new ErroResposta(erro.name()));
28	    }
